from pathlib import Path
import json
p=Path(__file__).parent

def read(name):return json.loads((p/name).read_text())
def exists(name):return (p/name).exists()
def perf_table(files):
 out=['|方案 / 对照|档位|A mean ms|B mean ms|Δmean µs|Δp99 µs|mean / p99 赢轮|逐轮 Δmean µs|','|---|---|---:|---:|---:|---:|---|---|']
 for label,file in files:
  if not exists(file):continue
  for profile,t in read(file)['tiers'].items():
   rr=t['rounds'];n=len(rr);out.append(f"|{label}|{profile}|{t['baseline_ms']:.6f}|{t['candidate_ms']:.6f}|{t['delta_ms']*1000:+.3f}|{t['p99_delta_ms']*1000:+.3f}|{sum(r['delta_ms']<0 for r in rr)}/{n} / {sum(r['p99_delta_ms']<0 for r in rr)}/{n}|"+' / '.join(f"{r['delta_ms']*1000:+.3f}"for r in rr)+'|')
 return out

